// Verbatim port of monsters.html inline script wrapped for the SPA — regenerated by
// scripts/wrap_p5_js.py; edit the generator, not this file.
import { exposeGlobals, unexposeGlobals } from '../../../lib/legacy.js';

export function init(ctx, d, G) {
  let _dead = false;
  void d; void G;
  let selectedTemplateId = null;
  let searchTimer = null;

  const CR_STEPS = [
    {label:'0',   val:0},    {label:'1/8', val:0.125},{label:'1/4', val:0.25},
    {label:'1/2', val:0.5},  {label:'1',   val:1},    {label:'2',   val:2},
    {label:'3',   val:3},    {label:'4',   val:4},    {label:'5',   val:5},
    {label:'6',   val:6},    {label:'7',   val:7},    {label:'8',   val:8},
    {label:'9',   val:9},    {label:'10',  val:10},   {label:'11',  val:11},
    {label:'12',  val:12},   {label:'13',  val:13},   {label:'14',  val:14},
    {label:'15',  val:15},   {label:'16',  val:16},   {label:'17',  val:17},
    {label:'18',  val:18},   {label:'19',  val:19},   {label:'20',  val:20},
    {label:'21',  val:21},   {label:'22',  val:22},   {label:'23',  val:23},
    {label:'24',  val:24},   {label:'25',  val:25},   {label:'26',  val:26},
    {label:'27',  val:27},   {label:'28',  val:28},   {label:'29',  val:29},
    {label:'30',  val:30},
  ];

  const searchInput    = document.getElementById('search-input');
  const resultsEl      = document.getElementById('search-results');
  const detPanel       = document.getElementById('detail-panel');
  const detPlaceholder = document.getElementById('detail-placeholder');
  let   _curTemplateId = null;   // monster currently shown in the detail panel

  searchInput.addEventListener('input', () => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(runSearch, 250);
  });

  function doSearch() {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(runSearch, 250);
  }

  function syncCrSliders(which) {
    let minIdx = parseInt(document.getElementById('cr-min-slider').value);
    let maxIdx = parseInt(document.getElementById('cr-max-slider').value);
    if (which === 'min' && minIdx > maxIdx) {
      document.getElementById('cr-max-slider').value = minIdx;
      maxIdx = minIdx;
    }
    if (which === 'max' && maxIdx < minIdx) {
      document.getElementById('cr-min-slider').value = maxIdx;
      minIdx = maxIdx;
    }
    document.getElementById('cr-range-display').textContent =
      'CR ' + CR_STEPS[minIdx].label + ' – ' + CR_STEPS[maxIdx].label;
    doSearch();
  }

  function resetFilters() {
    document.getElementById('filter-type').value   = '';
    document.getElementById('filter-size').value   = '';
    document.getElementById('filter-source').value = '';
    document.getElementById('cr-min-slider').value = 0;
    document.getElementById('cr-max-slider').value = CR_STEPS.length - 1;
    document.getElementById('cr-range-display').textContent = 'CR 0 – 30';
    searchInput.value = '';
    try { localStorage.removeItem(FILTER_KEY); } catch (e) {}
    doSearch();
  }

  // ── sticky filters: saved per browser, restored on the next page load ──────
  const FILTER_KEY = 'sp_monster_filters';

  function saveFilters() {
    try {
      localStorage.setItem(FILTER_KEY, JSON.stringify({
        q:      searchInput.value,
        type:   document.getElementById('filter-type').value,
        size:   document.getElementById('filter-size').value,
        source: document.getElementById('filter-source').value,
        crMin:  parseInt(document.getElementById('cr-min-slider').value),
        crMax:  parseInt(document.getElementById('cr-max-slider').value),
      }));
    } catch (e) {}
  }

  function restoreFilters() {
    let f = null;
    try { f = JSON.parse(localStorage.getItem(FILTER_KEY) || 'null'); } catch (e) {}
    if (!f) return;
    const setSel = (id, v) => {
      const el = document.getElementById(id);
      if (v && [...el.options].some(o => o.value === v)) el.value = v;
    };
    setSel('filter-type', f.type);
    setSel('filter-size', f.size);
    setSel('filter-source', f.source);
    const clamp = (v, d) => Number.isInteger(v) && v >= 0 && v < CR_STEPS.length ? v : d;
    let minIdx = clamp(f.crMin, 0), maxIdx = clamp(f.crMax, CR_STEPS.length - 1);
    if (minIdx > maxIdx) { minIdx = 0; maxIdx = CR_STEPS.length - 1; }
    document.getElementById('cr-min-slider').value = minIdx;
    document.getElementById('cr-max-slider').value = maxIdx;
    document.getElementById('cr-range-display').textContent =
      'CR ' + CR_STEPS[minIdx].label + ' – ' + CR_STEPS[maxIdx].label;
    if (typeof f.q === 'string') searchInput.value = f.q;
  }

  function runSearch() {
    saveFilters();
    const q      = searchInput.value.trim();
    const type   = document.getElementById('filter-type').value;
    const size   = document.getElementById('filter-size').value;
    const source = document.getElementById('filter-source').value;
    const minIdx = parseInt(document.getElementById('cr-min-slider').value);
    const maxIdx = parseInt(document.getElementById('cr-max-slider').value);
    const isDefaultCr = minIdx === 0 && maxIdx === CR_STEPS.length - 1;

    let url = `/ttrpg/monsters/search?q=${encodeURIComponent(q)}&limit=500`;
    if (type)   url += `&type=${encodeURIComponent(type)}`;
    if (size)   url += `&size=${encodeURIComponent(size)}`;
    if (source) url += `&source=${encodeURIComponent(source)}`;
    if (!isDefaultCr) {
      url += `&cr_min=${CR_STEPS[minIdx].val}&cr_max=${CR_STEPS[maxIdx].val}`;
    }

    fetch(url).then(r => r.json()).then(r => { if (!_dead) renderResults(r); });
  }

  function renderResults(monsters) {
    if (!monsters.length) {
      resultsEl.innerHTML = '<p class="text-muted small">No results.</p>';
      return;
    }
    const html = monsters.map(m => `
      <div class="d-flex align-items-center gap-2 p-2 monster-row"
           data-id="${m.template_id}" onclick="loadDetail(${m.template_id})"
           style="cursor:pointer;border-bottom:1px solid #2a2a2a;">
        <div class="flex-grow-1" style="min-width:0;">
          <div class="fw-bold text-truncate" style="color:var(--ttrpg-text);">${m.name}</div>
          <div class="small text-muted">${m.size} ${m.type} &bull; CR ${m.cr} &bull; HP ${m.hp_max} &bull; AC ${m.ac}</div>
        </div>
        ${m.source === 'homebrew' ? '<span class="badge bg-secondary">HB</span>' : ''}
      </div>
    `).join('');
    resultsEl.innerHTML = html;
  }

  function loadDetail(templateId) {
    // Highlight selection
    document.querySelectorAll('.monster-row').forEach(r => r.style.background = '');
    const row = document.querySelector(`.monster-row[data-id="${templateId}"]`);
    if (row) row.style.background = 'var(--ttrpg-primary)';

    fetch(`/ttrpg/monsters/${templateId}/detail`)
      .then(r => r.json())
      .then(data => renderDetail(templateId, data));
  }

  function mod(score) {
    const m = Math.floor((score - 10) / 2);
    return (m >= 0 ? '+' : '') + m;
  }

  function renderDetail(templateId, data) {
    selectedTemplateId = templateId;
    const s = data.stats || {};

    document.getElementById('det-name').textContent = data.name;
    document.getElementById('det-cr').textContent   = data.cr;
    document.getElementById('det-hp').textContent   = data.hp_max;
    document.getElementById('det-ac').textContent   = data.ac;
    document.getElementById('det-meta').textContent =
      [s.size, s.type, s.alignment].filter(Boolean).join(' ');

    _curTemplateId = templateId;
    const _hbMsg = document.getElementById('hb-img-msg'); if (_hbMsg) _hbMsg.textContent = '';
    const _hbFile = document.getElementById('hb-img-file'); if (_hbFile) _hbFile.value = '';
    const imgEl = document.getElementById('det-img');
    if (s.image) {
      imgEl.src = (s.image.startsWith('http') || s.image.startsWith('/static/') || s.image.startsWith('data:'))
        ? s.image : 'https://www.dnd5eapi.co' + s.image;
      imgEl.style.display = '';
    } else {
      imgEl.src = '';
      imgEl.style.display = 'none';
    }

    // Ability scores
    const abMap = {str:'strength',dex:'dexterity',con:'constitution',
                   int:'intelligence',wis:'wisdom',cha:'charisma'};
    let hasAb = false;
    for (const [ab, key] of Object.entries(abMap)) {
      if (s[key] !== undefined) {
        document.getElementById(`det-${ab}`).textContent     = s[key];
        document.getElementById(`det-${ab}-mod`).textContent = mod(s[key]);
        hasAb = true;
      }
    }
    document.getElementById('det-abilities').style.display = hasAb ? '' : 'none';

    // Traits
    const traits = [];
    if (s.speed) {
      const speeds = Object.entries(s.speed).map(([k,v]) => `${k} ${v}`).join(', ');
      traits.push(`<strong>Speed:</strong> ${speeds}`);
    }
    if (s.senses && Object.keys(s.senses).length)
      traits.push(`<strong>Senses:</strong> ${Object.entries(s.senses).map(([k,v])=>`${k} ${v}`).join(', ')}`);
    if (s.languages) traits.push(`<strong>Languages:</strong> ${s.languages}`);
    if (s.xp)        traits.push(`<strong>XP:</strong> ${s.xp}`);
    if (s.damage_immunities?.length)
      traits.push(`<strong>Immunities:</strong> ${s.damage_immunities.join(', ')}`);
    if (s.condition_immunities?.length)
      traits.push(`<strong>Condition Immunities:</strong> ${s.condition_immunities.map(c=>c.name||c).join(', ')}`);

    const specials = (s.special_abilities || []).map(a =>
      `<p class="mb-1"><strong>${a.name}.</strong> ${a.desc}</p>`).join('');

    document.getElementById('det-traits').innerHTML =
      traits.map(t => `<p class="mb-1">${t}</p>`).join('') + specials;

    // Actions
    const actions = s.actions || [];
    const actWrap = document.getElementById('det-actions-wrap');
    if (actions.length) {
      document.getElementById('det-actions').innerHTML =
        actions.map(a => `<p class="mb-1"><strong>${a.name}.</strong> ${a.desc}</p>`).join('');
      actWrap.style.display = '';
    } else {
      actWrap.style.display = 'none';
    }

    // Homebrew tools (edit / picture / delete)
    const delWrap = document.getElementById('homebrew-delete-wrap');
    if (data.source === 'homebrew') {
      document.getElementById('homebrew-delete-form').dataset.api =
        `/ttrpg/monsters/homebrew/${templateId}/delete`;
      document.getElementById('homebrew-edit-link').href =
        `/ttrpg/monsters/homebrew/${templateId}/edit`;
      delWrap.style.display = '';
    } else {
      delWrap.style.display = 'none';
    }

    detPanel.style.display = '';
    detPlaceholder.style.display = 'none';
  }

  // Upload / replace the picture on the currently-shown homebrew monster.
  // "Choose existing": point the homebrew monster at a shared upload by URL.
  function reuseMonsterImage() {
    if (!_curTemplateId) return;
    const msg = document.getElementById('hb-img-msg');
    spPickAsset({ kinds: ['image'], onPick: it => {
      if (msg) { msg.textContent = 'Linking…'; msg.style.color = ''; }
      fetch(`/ttrpg/monsters/homebrew/${_curTemplateId}/image`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image_url: it.url }) })
        .then(r => r.json()).then(d => {
          if (d && d.ok) {
            const imgEl = document.getElementById('det-img');
            if (imgEl) { imgEl.src = d.image_url + '?t=' + Date.now(); imgEl.style.display = ''; }
            if (msg) { msg.textContent = 'Picture set (reused).'; msg.style.color = '#7bc77b'; }
          } else if (msg) { msg.textContent = (d && d.error) || 'Failed.'; msg.style.color = '#e0a45c'; }
        }).catch(() => { if (msg) { msg.textContent = 'Failed.'; msg.style.color = '#e0a45c'; } });
    }});
  }

  function uploadMonsterImage() {
    const fileEl = document.getElementById('hb-img-file');
    const msg    = document.getElementById('hb-img-msg');
    const file   = fileEl && fileEl.files && fileEl.files[0];
    if (!_curTemplateId) return;
    if (!file) { if (msg) { msg.textContent = 'Choose an image first.'; msg.style.color = '#e0a45c'; } return; }
    const fd = new FormData();
    fd.append('image', file);
    if (msg) { msg.textContent = 'Uploading…'; msg.style.color = ''; }
    fetch(`/ttrpg/monsters/homebrew/${_curTemplateId}/image`, { method: 'POST', body: fd })
      .then(r => r.json())
      .then(d => {
        if (d && d.ok) {
          const imgEl = document.getElementById('det-img');
          if (imgEl) { imgEl.src = d.image_url + '?t=' + Date.now(); imgEl.style.display = ''; }
          if (msg) { msg.textContent = 'Picture updated.'; msg.style.color = '#7bc77b'; }
          if (fileEl) fileEl.value = '';
        } else if (msg) {
          msg.textContent = (d && d.error) || 'Upload failed.'; msg.style.color = '#e06666';
        }
      })
      .catch(() => { if (msg) { msg.textContent = 'Upload failed.'; msg.style.color = '#e06666'; } });
  }

  function addToSession() {
    if (!selectedTemplateId) { alert('Select a monster first.'); return; }
    const sessionId  = document.getElementById('session-select').value;
    const count      = parseInt(document.getElementById('add-count').value) || 1;
    const hpOverride = document.getElementById('hp-override').value;

    if (!sessionId) { alert('Select a session.'); return; }

    const body = new FormData();
    body.append('session_id', sessionId);
    body.append('count', count);
    if (hpOverride) body.append('hp_override', hpOverride);

    fetch(`/ttrpg/monsters/${selectedTemplateId}/add-to-session`, {method:'POST', body})
      .then(r => r.json())
      .then(data => {
        const el = document.getElementById('add-result');
        if (data.ok) {
          const names = data.created.map(c => c.display_name).join(', ');
          el.innerHTML = `<span class="text-success">&#10003; Added to "${data.session_title}": ${names}</span>`;
        } else {
          el.innerHTML = `<span class="text-danger">${data.error}</span>`;
        }
      });
  }

  // Start from defaults (prevent browser form-state restoration), then apply
  // the saved filters so they STICK across refreshes; Reset Filters clears them.
  document.getElementById('filter-type').value   = '';
  document.getElementById('filter-size').value   = '';
  document.getElementById('filter-source').value = '';
  document.getElementById('cr-min-slider').value = 0;
  document.getElementById('cr-max-slider').value = CR_STEPS.length - 1;
  document.getElementById('cr-range-display').textContent = 'CR 0 – 30';
  searchInput.value = '';
  restoreFilters();
  runSearch();

  const NAMES = ["doSearch", "syncCrSliders", "resetFilters", "saveFilters", "restoreFilters", "runSearch", "renderResults", "loadDetail", "mod", "renderDetail", "reuseMonsterImage", "uploadMonsterImage", "addToSession"];
  exposeGlobals({ doSearch, syncCrSliders, resetFilters, saveFilters, restoreFilters, runSearch, renderResults, loadDetail, mod, renderDetail, reuseMonsterImage, uploadMonsterImage, addToSession });
  return () => {
    _dead = true;
    try { clearTimeout(searchTimer); } catch (e) {}
    unexposeGlobals(NAMES);
  };
}
